    function readSharedA(){try{var m=document.cookie.match(/(?:^|;\s*)A=(\d{3,4})(?:;|$)/);if(!m)return null;var v=m[1],t=parseInt(v.slice(2),10);if(v.charAt(1)!=='0'&&v.charAt(1)!=='1')return null;if(!(t>=1&&t<=12))return null;return{l:v.charAt(0),m:v.charAt(1),t:t};}catch(e){return null;}}
    function writeSharedA(){try{var h=location.hostname,s='A='+(currentLang==='en'?'1':'0')+(isDarkMode?'0':'1')+(currentGlobalThemeIndex+1)+';path=/;max-age=31536000;SameSite=Lax';if(h==='jpedu.asia'||h.slice(-11)==='.jpedu.asia')s+=';domain=jpedu.asia';if(location.protocol==='https:')s+=';Secure';document.cookie=s;}catch(e){}}
    function savePhonePrefs(){try{localStorage.setItem('phone-theme-idx',String(currentGlobalThemeIndex));localStorage.setItem('phone-dark',isDarkMode?'1':'0');localStorage.setItem('phone-lang',currentLang);}catch(e){}}
    (function(){var hasLocal=false;try{var tk=localStorage.getItem('phone-theme-idx'),dk=localStorage.getItem('phone-dark'),lk=localStorage.getItem('phone-lang');if(tk!==null){var ti=parseInt(tk,10);if(ti>=0&&ti<12)currentGlobalThemeIndex=ti;hasLocal=true;}if(dk!==null){isDarkMode=dk==='1';hasLocal=true;}if(lk==='en'||lk==='zh'){currentLang=lk;hasLocal=true;}}catch(e){}var a=readSharedA();if(a){currentGlobalThemeIndex=a.t-1;isDarkMode=a.m==='0';currentLang=a.l==='1'?'en':'zh';savePhonePrefs();}else if(hasLocal){writeSharedA();}if(currentGlobalThemeIndex<6)quoteIndex=currentGlobalThemeIndex;else shopIndex=currentGlobalThemeIndex-6;})();
    let currentCategory = 'all';
    let filterOfficialOnly = false;
    let filterModOnly = false;
    const completedSteps = new Set([1, 3]);

    const openSiteGroups = new Set([
      'group-b-arm',
      'group-b-lean',
      'group-c-x86',
      'group-unknown',
      'group-na'
    ]);

    function siteEscape(text) {
      return String(text).replace(/[&<>"']/g, ch => ({
        '&': '&amp;',
        '<': '&lt;',
        '>': '&gt;',
        '"': '&quot;',
        "'": '&#39;'
      }[ch]));
    }

    // ================= 5. 核心主题渲染函数 =================
    function applyThemeByGlobalIndex(index) {
      currentGlobalThemeIndex = index;
      const themeObj = allThemes[index];
      if (!themeObj) return;

      if (index < 6) {
        quoteIndex = index;
      } else {
        shopIndex = index - 6;
      }

      const root = document.documentElement;
      root.style.setProperty('--orb-color-1', themeObj.orb1);
      root.style.setProperty('--orb-color-2', themeObj.orb2);
      root.style.setProperty('--refresh-btn-bg', themeObj.refreshBg);
      root.style.setProperty('--send-circle-bg', themeObj.sendCircleBg);
      root.style.setProperty('--theme-accent', themeObj.accent);
      root.style.setProperty('--theme-tag-bg', themeObj.tagBg);
      root.style.setProperty('--theme-tag-text', themeObj.tagText);
      root.style.setProperty('--search-glow', themeObj.glow);

      if (themeObj.isHolo) {
        root.setAttribute('data-holo', 'true');
      } else {
        root.removeAttribute('data-holo');
      }

      if (!isDarkMode) {
        root.style.setProperty('--page-bg', themeObj.pageBg);
      }

      const orbLeft = document.getElementById('orbLeft');
      const orbRight = document.getElementById('orbRight');
      if (!themeObj.isHolo) {
        const shift = index % 2 === 0 ? 1 : -1;
        orbLeft.style.transform = `translate(${shift * 14}px, ${-shift * 8}px) scale(${1 + shift * 0.05})`;
        orbRight.style.transform = `translate(${-shift * 14}px, ${shift * 8}px) scale(${1 - shift * 0.05})`;
      } else {
        orbLeft.style.transform = '';
        orbRight.style.transform = '';
      }

      updateSwatchActiveState();
    }

    function renderThemeSwatches() {
      const grid = document.getElementById('themeSwatchGrid');
      grid.innerHTML = allThemes.map((t, idx) => {
        const label = currentLang === 'zh' ? t.name : t.nameEn;
        const isActive = idx === currentGlobalThemeIndex ? 'active' : '';
        const holoClass = t.isHolo ? 'holo-animated' : '';
        return `
          <div class="theme-swatch-item ${isActive}" data-theme-idx="${idx}" onclick="selectThemeFromPanel(${idx})">
            <span class="swatch-orb-preview ${holoClass}" style="background: linear-gradient(135deg, ${t.orb1} 0%, ${t.orb2} 65%, ${t.refreshBg} 100%);"></span>
            <span class="swatch-label">${label}</span>
          </div>
        `;
      }).join('');
    }

    function updateSwatchActiveState() {
      document.querySelectorAll('.theme-swatch-item').forEach(el => {
        const idx = Number(el.getAttribute('data-theme-idx'));
        el.classList.toggle('active', idx === currentGlobalThemeIndex);
      });
    }

    function openThemePanel() {
      document.getElementById('themePopover').classList.add('open');
      document.getElementById('themeBackdrop').classList.add('open');
      if (navigator.vibrate) navigator.vibrate(18);
    }

    function closeThemePanel() {
      document.getElementById('themePopover').classList.remove('open');
      document.getElementById('themeBackdrop').classList.remove('open');
      document.querySelectorAll('.theme-swatch-item').forEach(el => el.classList.remove('sliding-hover'));
    }

    function selectThemeFromPanel(idx) {
      applyThemeByGlobalIndex(idx);
      savePhonePrefs();
      writeSharedA();
      closeThemePanel();
    }

    (function initThemeButtonGestures() {
      const btn = document.getElementById('darkModeBtn');
      let pressTimer = null;
      let isLongPressTriggered = false;
      let isPointerDown = false;
      let lastHoveredIdx = null;

      btn.addEventListener('pointerdown', (e) => {
        if (e.button && e.button !== 0) return;
        isPointerDown = true;
        isLongPressTriggered = false;
        lastHoveredIdx = null;
        btn.classList.add('pressing');

        try { btn.setPointerCapture(e.pointerId); } catch (_) {}

        pressTimer = setTimeout(() => {
          if (!isPointerDown) return;
          isLongPressTriggered = true;
          openThemePanel();
        }, 340);
      });

      btn.addEventListener('pointermove', (e) => {
        if (!isPointerDown || !isLongPressTriggered) return;

        const targetEl = document.elementFromPoint(e.clientX, e.clientY);
        const swatchItem = targetEl ? targetEl.closest('.theme-swatch-item') : null;

        document.querySelectorAll('.theme-swatch-item').forEach(el => {
          el.classList.toggle('sliding-hover', el === swatchItem);
        });

        if (swatchItem) {
          const idx = Number(swatchItem.getAttribute('data-theme-idx'));
          if (idx !== lastHoveredIdx) {
            lastHoveredIdx = idx;
            applyThemeByGlobalIndex(idx);
            if (navigator.vibrate) navigator.vibrate(8);
          }
        }
      });

      const finishGesture = () => {
        if (!isPointerDown) return;
        isPointerDown = false;
        clearTimeout(pressTimer);
        btn.classList.remove('pressing');

        if (!isLongPressTriggered) {
          const popover = document.getElementById('themePopover');
          if (popover.classList.contains('open')) {
            closeThemePanel();
          } else {
            toggleDarkMode();
          }
        } else if (lastHoveredIdx !== null) {
          savePhonePrefs();
          writeSharedA();
          closeThemePanel();
        }
      };

      btn.addEventListener('pointerup', finishGesture);
      btn.addEventListener('pointercancel', finishGesture);
      btn.addEventListener('contextmenu', e => e.preventDefault());
    })();

    // ================= 6. Tab 切换 =================
    function switchTab(tabName) {
      if (currentTab === tabName) return;
      currentTab = tabName;

      const tabsContainer = document.getElementById('geminiTabs');
      tabsContainer.setAttribute('data-active', tabName);
      document.getElementById('tabMatrix').classList.toggle('active', tabName === 'matrix');
      document.getElementById('tabGuide').classList.toggle('active', tabName === 'guide');

      const targetGlobalIdx = tabName === 'matrix' ? quoteIndex : (6 + shopIndex);
      applyThemeByGlobalIndex(targetGlobalIdx);

      const grid = document.getElementById('contentGrid');
      grid.classList.add('switching');
      setTimeout(() => {
        renderAll();
        grid.classList.remove('switching');
      }, 180);
    }

    function handleRefresh() {
      const btn = document.getElementById('refreshBtn');
      btn.classList.add('spinning');
      setTimeout(() => btn.classList.remove('spinning'), 520);

      const nextIdx = (currentGlobalThemeIndex + 1) % allThemes.length;
      applyThemeByGlobalIndex(nextIdx);
      savePhonePrefs();
      writeSharedA();

    }

