      document.getElementById('panelTitle').textContent = zh ? '12色弥散主题' : '12 Aura Themes';
      document.getElementById('panelHint').textContent = zh ? '滑动或点击选择' : 'Slide or tap';
      document.getElementById('chkOfficialText').textContent = zh ? '只看有官网价/官方文档' : 'Official Price/Docs Only';
      document.getElementById('chkModText').textContent = zh ? '只看含一键新机/改机说明' : 'One-Click Modding Only';

      savePhonePrefs();
      writeSharedA();
      renderThemeSwatches();
      renderAll();
